CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events WHEN coalesce((SELECT audit_retention_authorized FROM bridge_config WHERE singleton_id=1),0)<>1 BEGIN SELECT RAISE(ABORT,'Audit retention uses a separately authorized maintenance transaction'); END;
COMMIT;

